</main><script>(function(){var b=document.getElementById('aiads-generate'),s=document.getElementById('aiads-copy-status');if(!b)return;b.addEventListener('click',function(){var p=document.getElementById('aiads-prompt').value.trim();if(!p){s.textContent='Describe your ad first.';return}b.disabled=true;s.textContent='Generating…';var d=new URLSearchParams();d.append('<?= html_escape($csrfName); ?>','<?= html_escape($csrfHash); ?>');d.append('prompt',p);d.append('product_id',(document.querySelector('input[name=product_id]:checked')||{}).value||'0');fetch('<?= base_url('marketing/ai_ads/generate_copy'); ?>',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},credentials:'same-origin',body:d.toString()}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'AI copy is unavailable.');document.getElementById('aiads-headline').value=r.copy.headline;document.getElementById('aiads-body').value=r.copy.body;s.textContent='Review and edit before saving.'}).catch(function(e){s.textContent=e.message||'AI copy unavailable.'}).finally(function(){b.disabled=false})})})();</script><?php $this->load->view('mobile/bottom_nav',array('active'=>'more')); ?><?php $this->load->view('mobile/chat'); ?></body></html>
